Given the head of a singly linked list and an integer k, rotate the list to the left by k positions and return the updated head.Examples:Input: k = 4 Output: 50 -> 10 -> 20 -> 30 -> 40Explanation: After rotating the linked list to the left by 4 places, the 5th node, i.e node 50 becomes the head of the linked list and next pointer of node 50 points to node 10. Input:  k = 6 Output: 30 -> 40 -> 10 -> 20 Explanation: After rotating the list left by 6 positions, the node with value 30 becomes the new head, and the node with value 40 points to the node with value 10. Try It YourselfTable of Content[Naive Approach] Shifting head node to the end k times - O(n × k) Time and O(1) Space[Expected Approach] By changing pointer of kth node - O(n) Time and O(1) Space[Naive Approach] Shifting head node to the end k times - O(n × k) Time and O(1) SpaceTo rotate a linked list to the left k places, we can repeatedly move the head node to the end of the linked list k times.
            C++

    #include <iostream>
using namespace std;

class Node {
  public:
    int data;
    Node *next;
    Node(int new_data) {
        data = new_data;
        next = nullptr;
    }
};

Node *rotate(Node *head, int k) {
    if (k == 0 || head == nullptr)
        return head;

    // rotate the list by k nodes
    for (int i = 0; i < k; ++i) {
        Node *curr = head;
        while (curr->next != nullptr)
            curr = curr->next;

        // move the first node to the last
        curr->next = head;
        curr = curr->next;
        head = head->next;
        curr->next = nullptr;
    }
    return head;
}

void printList(Node *node) {
    while (node != nullptr) {
        cout << node->data;
        if(node->next != NULL){
            cout << " -> ";
        }
        node = node->next;
    }
    cout << endl;
}

int main() {

    Node *head = new Node(10);
    head->next = new Node(20);
    head->next->next = new Node(30);
    head->next->next->next = new Node(40);

    head = rotate(head, 6);
    printList(head);

    return 0;
}


